// ================================================================
// STEP 1 — Get your FREE rss2json API key (takes 2 minutes)
// 1. Go to: https://rss2json.com
// 2. Click "Sign Up Free" (top right)
// 3. Create account with any email — no credit card needed
// 4. After login, your API key is shown on the Dashboard page
// 5. Copy it and paste below
// ================================================================
const RSS2JSON_KEY = 'PASTE_YOUR_KEY_HERE';

const channels = [
  { id: 'UCsBjURrPoezykLs9EqgamOA', name: 'Fireship',       cat: 'Tech/Dev' },
  { id: 'UCHlNU7kIZhRgSbhHvFoy72w', name: 'Hugging Face',   cat: 'AI Tools' },
  { id: 'UCbfYPyITQ-7l4upoX8nvctg', name: 'Two Min Papers', cat: 'AI Research' },
  { id: 'UCNJ1Ymd5yFuUPtn21xtRbbw', name: 'AI Explained',   cat: 'AI News' },
  { id: 'UCSHZKyawb77ixDdsGog4iWA', name: 'Lex Fridman',    cat: 'Tech/AI/Biz' },
  { id: 'UCxIJaCMEptJjxmmQgGFsnCg', name: 'Y Combinator',   cat: 'Startup' },
  { id: 'UCnxrdFPXJMeHru_b4Q_vTPQ', name: 'NetworkChuck',   cat: 'Networking' },
  { id: 'UCZHmQk67mSJgfCCTn7xBfew', name: 'Yannic Kilcher', cat: 'AI/ML' },
  { id: 'UCBJycsmduvYEL83R_U4JriQ', name: 'MKBHD',          cat: 'Tech Reviews' },
  { id: 'UC9-y-6csu5WGm29I7JiwpnA', name: 'Computerphile',  cat: 'CS/Tech' },
  { id: 'UCCjyq_K1Xwfg8Lndy7lKMpA', name: 'TechCrunch',     cat: 'Tech News' },
  { id: 'UCESLZhusAkFfsNsApnjF_Cg', name: 'All-In Podcast', cat: 'B2B/Startup' }
];

const CLAUDE_KEY   = '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';
const CLAUDE_MODEL = 'claude-sonnet-4-6';
const DIGEST_EMAIL = 'countrycoveinc@gmail.com';

const hasKey = RSS2JSON_KEY && RSS2JSON_KEY.length > 10 && RSS2JSON_KEY !== 'PASTE_YOUR_KEY_HERE';
if (!hasKey) console.log('[Config] WARNING: No rss2json API key set. Get a FREE key at rss2json.com — without it, videos will be empty!');
else          console.log('[Config] rss2json API key found.');

const cutoff = new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString();
const today  = new Date().toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric', timeZone:'America/New_York' });
console.log('[Config] ' + channels.length + ' channels | cutoff: ' + cutoff);

return [{ json: { channels, RSS2JSON_KEY, hasKey, CLAUDE_KEY, CLAUDE_MODEL, DIGEST_EMAIL, cutoff, today } }];

const cfg = $('Config: Channels + Settings').item.json;

// Get TechCrunch XML
let tcXml = '';
try {
  const raw = $input.item.json;
  tcXml = (typeof raw === 'string') ? raw : (raw.data || raw.body || '');
} catch(e) { tcXml = ''; }

// Parse TechCrunch RSS 2.0 items
function parseRSS(xml, limit) {
  const items = [];
  let pos = 0;
  while (items.length < (limit || 12)) {
    const s = xml.indexOf('<item>', pos);
    if (s < 0) break;
    const e = xml.indexOf('</item>', s);
    if (e < 0) break;
    const b = xml.slice(s + 6, e);
    pos = e + 7;
    function gv(tag) {
      const open = '<' + tag + '>', close = '</' + tag + '>';
      const si = b.indexOf(open), ei = b.indexOf(close);
      if (si < 0 || ei < 0) return '';
      let v = b.slice(si + open.length, ei);
      const cs = v.indexOf('<![CDATA['), ce = v.indexOf(']]>');
      if (cs >= 0 && ce > cs) v = v.slice(cs + 9, ce);
      return v.replace(/<[^>]+>/g,'').trim();
    }
    const title = gv('title');
    if (!title || title.length < 4) continue;
    const ls = b.indexOf('<link>'), le = b.indexOf('</link>');
    const link = (ls >= 0 && le >= 0) ? b.slice(ls + 6, le).trim() : gv('guid');
    items.push({ source: 'TechCrunch', category: 'Trending', title, url: link, description: gv('description').slice(0, 250) });
  }
  return items;
}

const trendingItems = parseRSS(tcXml, 12);
console.log('[Trending] ' + trendingItems.length + ' TechCrunch items');

// Build one item per channel for the Split loop
// rss2json.com proxies YouTube feeds and IS allowed from cloud servers
// With API key: 10,000 requests/day free | Without: shared pool = rate limited
return cfg.channels.map(function(ch) {
  const ytFeedUrl = 'https://www.youtube.com/feeds/videos.xml?channel_id=' + ch.id;
  const keyParam  = cfg.hasKey ? ('&api_key=' + cfg.RSS2JSON_KEY + '&count=15') : '&count=10';
  const r2jUrl    = 'https://api.rss2json.com/v1/api.json?rss_url=' + encodeURIComponent(ytFeedUrl) + keyParam;
  return {
    json: {
      channelId:    ch.id,
      channelName:  ch.name,
      channelCat:   ch.cat,
      r2jUrl:       r2jUrl,
      cutoff:       cfg.cutoff,
      today:        cfg.today,
      CLAUDE_KEY:   cfg.CLAUDE_KEY,
      CLAUDE_MODEL: cfg.CLAUDE_MODEL,
      DIGEST_EMAIL: cfg.DIGEST_EMAIL,
      trendingItems: trendingItems
    }
  };
});

// Get channel context from the Split node (always available even if HTTP failed)
let chInfo = {};
try { chInfo = $('Split: One Channel at a Time').item.json || {}; } catch(e) {}

const chName        = chInfo.channelName || 'Unknown';
const chCat         = chInfo.channelCat  || 'General';
const cutoff        = new Date(chInfo.cutoff || (Date.now() - 7 * 24 * 3600 * 1000));
const trendingItems = Array.isArray(chInfo.trendingItems) ? chInfo.trendingItems : [];
const meta = {
  today:        chInfo.today,
  CLAUDE_KEY:   chInfo.CLAUDE_KEY,
  CLAUDE_MODEL: chInfo.CLAUDE_MODEL,
  DIGEST_EMAIL: chInfo.DIGEST_EMAIL
};

const EMPTY = [{ json: Object.assign({ channelName: chName, category: chCat, videos: [], trendingItems }, meta) }];

// Read rss2json JSON response from HTTP node
let raw = null;
try { raw = $input.item.json; } catch(e) {
  console.log('[' + chName + '] Cannot read HTTP response: ' + e.message);
  return EMPTY;
}

// Log raw shape for debugging
const rawKeys = (raw && typeof raw === 'object') ? Object.keys(raw).join(',') : typeof raw;
console.log('[' + chName + '] raw keys: ' + rawKeys);

// Unwrap any n8n envelope
let d = raw;
if (!d) { console.log('[' + chName + '] null response'); return EMPTY; }
if (typeof d === 'string') { try { d = JSON.parse(d); } catch(e) { console.log('[' + chName + '] string parse failed'); return EMPTY; } }
if (d.body  && typeof d.body  === 'string') { try { d = JSON.parse(d.body);  } catch(e) { console.log('[' + chName + '] body parse failed'); return EMPTY; } }
if (d.data  && typeof d.data  === 'object' && d.data.status) { d = d.data; }
if (d.json  && typeof d.json  === 'object') { d = d.json; }

const status = (d && d.status) || '';
const items  = (d && Array.isArray(d.items)) ? d.items : [];
const msgStr = (d && d.message) ? ' | msg: ' + d.message : '';
console.log('[' + chName + '] rss2json status=' + status + ' items=' + items.length + msgStr);

if (status !== 'ok') {
  if (d && d.message && d.message.indexOf('api_key') >= 0) {
    console.log('[' + chName + '] API KEY REQUIRED — get free key at rss2json.com and set RSS2JSON_KEY in Config node');
  } else {
    console.log('[' + chName + '] SKIP — rss2json returned: ' + status);
  }
  return EMPTY;
}

if (items.length === 0) {
  console.log('[' + chName + '] No items in feed');
  return EMPTY;
}

// Parse video items from rss2json response
const videos = [];
for (var i = 0; i < items.length; i++) {
  try {
    const item = items[i];
    // Published date filter
    const pub = (item.pubDate || '').replace(' ', 'T');
    if (pub) {
      const pubDate = new Date(pub);
      if (!isNaN(pubDate.getTime()) && pubDate < cutoff) continue;
    }
    // Must be a YouTube video URL
    const url = item.link || '';
    if (!url || !url.includes('youtube.com/watch')) continue;
    const vi    = url.indexOf('v=');
    const vidId = (vi >= 0) ? url.slice(vi + 2, vi + 13) : null;
    if (!vidId || vidId.length !== 11) continue;
    const title = (item.title || '')
      .replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>').trim();
    if (!title) continue;
    const desc  = (item.description || '')
      .replace(/<[^>]+>/g,'')
      .replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>')
      .trim().slice(0, 500);
    const thumb = item.thumbnail || ('https://i.ytimg.com/vi/' + vidId + '/hqdefault.jpg');
    videos.push({
      videoId:     vidId,
      title:       title,
      url:         url,
      published:   item.pubDate || '',
      description: desc,
      thumbnail:   thumb,
      views:       0,
      channel:     chName,
      category:    chCat
    });
  } catch(ex) {
    console.log('[' + chName + '] item parse error: ' + ex.message);
  }
}

console.log('[' + chName + '] => ' + videos.length + ' videos within 7d cutoff');
return [{ json: Object.assign({ channelName: chName, category: chCat, videos: videos, trendingItems: trendingItems }, meta) }];

const allChannels = $input.item.json.allChannels || [];

let allVideos = [], trendingItems = [];
let today = '', CLAUDE_KEY = '', CLAUDE_MODEL = '', DIGEST_EMAIL = '';

for (var i = 0; i < allChannels.length; i++) {
  const ch = allChannels[i];
  if (Array.isArray(ch.videos) && ch.videos.length > 0) allVideos = allVideos.concat(ch.videos);
  if (Array.isArray(ch.trendingItems) && ch.trendingItems.length > trendingItems.length) trendingItems = ch.trendingItems;
  if (ch.today)        today        = ch.today;
  if (ch.CLAUDE_KEY)   CLAUDE_KEY   = ch.CLAUDE_KEY;
  if (ch.CLAUDE_MODEL) CLAUDE_MODEL = ch.CLAUDE_MODEL;
  if (ch.DIGEST_EMAIL) DIGEST_EMAIL = ch.DIGEST_EMAIL;
}

// Deduplicate by videoId, sort newest first
const seen = new Set();
allVideos = allVideos
  .filter(function(v) { if (seen.has(v.videoId)) return false; seen.add(v.videoId); return true; })
  .sort(function(a, b) { return new Date(b.published || 0) - new Date(a.published || 0); });

console.log('[Build] ' + allVideos.length + ' unique videos | ' + trendingItems.length + ' trending');
if (allVideos.length === 0) {
  console.log('[Build] WARNING: 0 videos found. Check rss2json API key in Config node. Get free key at rss2json.com');
}

const videoSection = allVideos.length > 0
  ? allVideos.map(function(v, i) {
      return (i+1) + '. [' + v.category + '] ' + v.channel + ': "' + v.title + '"\nLink: ' + v.url + '\nDescription: ' + (v.description || '(none)').slice(0, 300);
    }).join('\n\n')
  : 'No YouTube videos found this week. Focus digest on the trending news items below.';

const trendingSection = trendingItems.length > 0
  ? trendingItems.map(function(t) { return '• ' + t.title + (t.url ? ' | ' + t.url : '') + (t.description ? ' — ' + t.description.slice(0,120) : ''); }).join('\n')
  : 'No trending data available.';

const prompt =
  'You are a sharp AI + Tech + Business curator. Today is ' + today + '.\n\n'
  + '== TRENDING TECH NEWS (TechCrunch, last 24h) ==\n' + trendingSection + '\n\n'
  + '== YOUTUBE VIDEOS THIS WEEK (' + allVideos.length + ' videos from 12 tracked channels) ==\n' + videoSection + '\n\n'
  + '== YOUR TASK ==\n'
  + 'Write a high-value daily digest. Use EXACTLY these section headers (ALL CAPS):\n\n'
  + 'HEADLINE OF THE DAY\nOne bold sentence — the single most important story right now.\n\n'
  + 'TOP VIDEOS THIS WEEK\nFor each top video: title | channel | 2-3 sentence summary drawing from the description | direct link\n\n'
  + 'KEY INSIGHTS\n5 specific, non-obvious bullets drawn directly from the video descriptions. Quote actual details, numbers, or concepts mentioned.\n\n'
  + 'AI & AUTOMATION HIGHLIGHTS\n3 bullets on the most important AI/automation developments from this week content.\n\n'
  + 'BUSINESS & STARTUP SIGNALS\n2 bullets — key business/startup/SaaS signals from TechCrunch and YouTube.\n\n'
  + 'TRENDING IN TECH\n3 TechCrunch stories with a one-line commentary on why each matters right now.\n\n'
  + 'WHAT TO BUILD THIS WEEK\n1 specific, concrete product or automation idea inspired directly by this week content.\n\n'
  + 'QUOTE OF THE DAY\nOne memorable, specific insight from a video description (cite the channel name).\n\n'
  + 'Tone: direct, intelligent, no filler. Plain text — NO markdown asterisks or headers.';

const claudeRequest = JSON.stringify({
  model:      CLAUDE_MODEL || 'claude-sonnet-4-6',
  max_tokens: 4000,
  messages:   [{ role: 'user', content: prompt }]
});

return [{ json: { allVideos, trendingItems, totalVideos: allVideos.length, today, CLAUDE_KEY, CLAUDE_MODEL, DIGEST_EMAIL, claudeRequest } }];

const prev       = $('Code: Build Claude Request').item.json;
const claudeResp = $input.item.json;

let digestText = 'Digest generation failed — Claude API did not respond.';
try {
  const t = claudeResp && claudeResp.content && claudeResp.content[0] && claudeResp.content[0].text;
  if (t && t.length > 50) digestText = t;
} catch(e) { console.log('[Claude parse] ' + e.message); }

const allVideos     = prev.allVideos     || [];
const trendingItems = prev.trendingItems || [];

function timeAgo(s) {
  if (!s) return '';
  const d = Math.floor((Date.now() - new Date(s.replace(' ','T')).getTime()) / 86400000);
  return d <= 0 ? 'Today' : d + 'd ago';
}

// Video thumbnail cards (top 6)
const videoCards = allVideos.slice(0, 6).map(function(v, i) {
  return '<div style="border:1px solid #1f2937;border-radius:10px;overflow:hidden;margin-bottom:14px;background:#111827;">'
    + '<table cellpadding="0" cellspacing="0" width="100%"><tr>'
    + '<td width="150" valign="top" style="padding:0;">'
    + '<a href="' + v.url + '" target="_blank"><img src="' + (v.thumbnail||'') + '" width="150" height="85" alt="" style="display:block;"/></a>'
    + '</td><td valign="top" style="padding:10px 12px;">'
    + '<p style="margin:0 0 3px;font-size:10px;color:#6b7280;">#' + (i+1) + ' &nbsp;<span style="background:#1d4ed8;color:#bfdbfe;padding:1px 7px;border-radius:8px;font-size:9px;font-weight:700;">' + (v.category||'') + '</span> &nbsp;' + timeAgo(v.published) + '</p>'
    + '<a href="' + v.url + '" target="_blank" style="text-decoration:none;"><p style="margin:0 0 3px;color:#f9fafb;font-size:13px;font-weight:700;line-height:1.4;">' + (v.title||'') + '</p></a>'
    + '<p style="margin:0;color:#9ca3af;font-size:11px;">&#128250; ' + (v.channel||'') + '</p>'
    + '</td></tr></table></div>';
}).join('');

// Trending pills
const trendingHtml = trendingItems.slice(0, 6).map(function(t) {
  return '<p style="margin:0 0 7px;color:#d1d5db;font-size:12px;border-left:3px solid #7c3aed;padding-left:8px;">'
    + '<a href="' + (t.url||'#') + '" style="color:#a78bfa;text-decoration:none;font-weight:600;">' + (t.title||'') + '</a></p>';
}).join('');

// Section extractor
const SECTIONS = ['HEADLINE OF THE DAY','TOP VIDEOS THIS WEEK','KEY INSIGHTS','AI & AUTOMATION HIGHLIGHTS','BUSINESS & STARTUP SIGNALS','TRENDING IN TECH','WHAT TO BUILD THIS WEEK','QUOTE OF THE DAY'];
function extract(text, heading) {
  const idx = text.indexOf(heading);
  if (idx < 0) return '';
  const start = idx + heading.length;
  let end = text.length;
  SECTIONS.forEach(function(s) {
    if (s === heading) return;
    const ni = text.indexOf(s, start);
    if (ni > 0 && ni < end) end = ni;
  });
  return text.slice(start, end).trim();
}
function sectionBlock(heading, content, color) {
  if (!content) return '';
  const lines = content.split('\n').filter(function(l) { return l.trim().length > 0; });
  const body = lines.map(function(line) {
    const linked = line.replace(/(https?:\/\/[^\s]+)/g, '<a href="$1" style="color:#818cf8;">$1</a>');
    if (/^[•\-*]|^\d+\./.test(line.trim())) return '<p style="margin:4px 0 4px 8px;color:#d1d5db;font-size:13px;">' + linked + '</p>';
    return '<p style="margin:4px 0;color:#e5e7eb;font-size:13px;line-height:1.65;">' + linked + '</p>';
  }).join('');
  return '<div style="margin-bottom:22px;"><p style="margin:0 0 8px;font-size:10px;font-weight:800;color:' + color + ';text-transform:uppercase;letter-spacing:1.5px;">' + heading + '</p>' + body + '</div>';
}

const headline = extract(digestText, 'HEADLINE OF THE DAY');
const subject  = '\uD83D\uDCFA ' + (prev.today||'') + ' \u2014 AI+Tech Digest (' + prev.totalVideos + ' videos, ' + trendingItems.length + ' trending)';

const emailHtml = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>'
  + '<body style="margin:0;padding:0;background:#030712;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif;">'
  + '<div style="max-width:660px;margin:0 auto;padding:20px 0;">'

  // Header
  + '<div style="background:linear-gradient(135deg,#1e1b4b,#312e81,#1e1b4b);padding:36px 32px;border-radius:14px 14px 0 0;text-align:center;">'
  + '<div style="font-size:44px;">\uD83D\uDCFA</div>'
  + '<h1 style="margin:8px 0 4px;color:#fff;font-size:22px;font-weight:900;">AI + Tech + Business Daily Digest</h1>'
  + '<p style="color:rgba(255,255,255,0.65);margin:0 0 14px;font-size:13px;">' + (prev.today||'') + '</p>'
  + '<span style="background:rgba(255,255,255,0.1);color:#a5b4fc;padding:4px 12px;border-radius:20px;font-size:11px;font-weight:700;">\uD83D\uDCF9 ' + prev.totalVideos + ' VIDEOS</span>'
  + ' <span style="background:rgba(255,255,255,0.1);color:#fcd34d;padding:4px 12px;border-radius:20px;font-size:11px;font-weight:700;">\uD83D\uDD25 ' + trendingItems.length + ' TRENDING</span>'
  + '</div>'

  // Headline banner
  + (headline ? '<div style="background:#1f2937;border-left:4px solid #7c3aed;padding:16px 20px;"><p style="margin:0 0 4px;font-size:10px;font-weight:800;color:#7c3aed;text-transform:uppercase;letter-spacing:1.5px;">\uD83D\uDCA5 HEADLINE OF THE DAY</p><p style="margin:0;font-size:15px;color:#f9fafb;font-weight:700;line-height:1.5;">' + headline + '</p></div>' : '')

  // Body
  + '<div style="background:#111827;padding:26px 30px;">'
  + (allVideos.length > 0
    ? '<p style="margin:0 0 12px;font-size:10px;font-weight:800;color:#6366f1;text-transform:uppercase;letter-spacing:1.5px;">\uD83C\uDFC6 TOP VIDEOS THIS WEEK</p>' + videoCards
    : '<div style="background:#1f2937;border:1px solid #374151;border-radius:8px;padding:14px;margin-bottom:20px;"><p style="margin:0;color:#f87171;font-size:13px;">&#9888; No YouTube videos were fetched. <strong>Action required:</strong> Get a free API key at <a href="https://rss2json.com" style="color:#818cf8;">rss2json.com</a> and paste it in the Config node as RSS2JSON_KEY.</p></div>')

  + sectionBlock('\uD83D\uDCC4 VIDEO SUMMARIES', extract(digestText,'TOP VIDEOS THIS WEEK'), '#818cf8')
  + sectionBlock('\uD83D\uDCA1 KEY INSIGHTS', extract(digestText,'KEY INSIGHTS'), '#34d399')
  + sectionBlock('\uD83E\uDD16 AI & AUTOMATION HIGHLIGHTS', extract(digestText,'AI & AUTOMATION HIGHLIGHTS'), '#60a5fa')
  + sectionBlock('\uD83D\uDCBC BUSINESS & STARTUP SIGNALS', extract(digestText,'BUSINESS & STARTUP SIGNALS'), '#f59e0b')

  + (trendingItems.length > 0 ? '<div style="margin-bottom:22px;"><p style="margin:0 0 10px;font-size:10px;font-weight:800;color:#f87171;text-transform:uppercase;letter-spacing:1.5px;">\uD83D\uDD25 TRENDING IN TECH</p>' + trendingHtml + '</div>' : '')

  + sectionBlock('\uD83D\uDD28 WHAT TO BUILD THIS WEEK', extract(digestText,'WHAT TO BUILD THIS WEEK'), '#a3e635')

  + (extract(digestText,'QUOTE OF THE DAY') ? '<div style="background:#1f2937;border:1px solid #374151;border-radius:10px;padding:18px;margin-bottom:20px;"><p style="margin:0 0 6px;font-size:10px;font-weight:800;color:#fbbf24;text-transform:uppercase;letter-spacing:1.5px;">\uD83D\uDDE8 QUOTE OF THE DAY</p><p style="margin:0;font-size:14px;color:#f3f4f6;font-style:italic;line-height:1.7;">' + extract(digestText,'QUOTE OF THE DAY') + '</p></div>' : '')

  + '</div>'
  + '<div style="background:#030712;padding:14px;text-align:center;border-radius:0 0 14px 14px;border-top:1px solid #1f2937;"><p style="color:#374151;font-size:10px;margin:0;">\uD83E\uDD16 JHD Advisor AI &mdash; rss2json + Claude API &mdash; Daily 8AM ET</p></div>'
  + '</div></body></html>';

console.log('[Email] Subject: ' + subject);
return [{ json: Object.assign({}, prev, { emailHtml, subject, digestText }) }];
